css:
#loader-22 {
  width: 100px;
  height: 30px;
  display: flex;
  justify-content: center;
}
#loader-22:before,
#loader-22:after {
  content: "";
  background: #000;
  width: 15px;
  clip-path: polygon(0 10px,calc(100% - 15px) 10px,calc(100% - 15px) 0,100% 50%,calc(100% - 15px) 100%,calc(100% - 15px) calc(100% - 10px),0 calc(100% - 10px));
  animation: l2 1s infinite linear;
}
#loader-22:before {
  transform: scaleX(-1);
}
@keyframes l2 {
  90%,100%{flex-grow: .5}
}
